        ['string', 'null', 'null'] => match ($parts[0]) {
            'tenant' => TenantRef::global(),
            'context' => AssignmentScopeRef::global(),
            default => null,
        },
        default => null,
    };

    return $ref ?? self::decodeComposite($parts) ?? throw new InvalidIdentityException(
